var vlookat = 0;
var hlookat = 0;

// Lấy vị trí camera hiện tại
var cx = krpano.view.tx;
var cy = krpano.view.ty;
var cz = krpano.view.tz;

// Tính góc giữa camera và điểm cần nhìn
var dx = tx - cx;
var dy = ty - cy;
var dz = tz - cz;

// Tính góc nhìn theo chiều ngang (hlookat)
hlookat = Math.atan2(dx, dz) * 180 / Math.PI;

// Tính góc nhìn theo chiều dọc (vlookat)
var dist = Math.sqrt(dx*dx + dz*dz);
vlookat = Math.atan2(dy, dist) * 180 / Math.PI;

// Set góc nhìn mới
krpano.call("tween(view.hlookat, " + hlookat + ", " + time + ", easeInOutQuad);");
krpano.call("tween(view.vlookat, " + vlookat + ", " + time + ", easeInOutQuad);");
